std::string Encryption::chacha20_xor(const Key &key, std::uint32_t counter, const Nonce &nonce, const std::string &data)
{
    std::string out(data.size(), '\0');
    std::uint8_t block[64];
    for (std::size_t offset = 0; offset < data.size(); offset += 64, ++counter)
    {
        chacha20_block(key, counter, nonce, block);
        std::size_t n = std::min<std::size_t>(64, data.size() - offset);
        for (std::size_t i = 0; i < n; ++i)
        {
            out[offset + i] = static_cast<char>(static_cast<std::uint8_t>(data[offset + i]) ^ block[i]);
        }
    }
    secure_zero(block, sizeof(block));
    return out;
}

// Poly1305 with 26-bit limbs (the well-known "poly1305-donna" 32-bit layout).
// Computes ((sum of message blocks, each as a number with a high bit added) * r^i) mod 2^130-5, + s.
std::array<std::uint8_t, Encryption::TAG_SIZE> Encryption::poly1305(const std::array<std::uint8_t, 32> &one_time_key,
                                                                    const std::string &message)
{
    const std::uint8_t *k = one_time_key.data();

    // r = first 16 bytes, "clamped" as the RFC requires
    const std::uint32_t r0 = (load32_le(k + 0)) & 0x3ffffff;
    const std::uint32_t r1 = (load32_le(k + 3) >> 2) & 0x3ffff03;
    const std::uint32_t r2 = (load32_le(k + 6) >> 4) & 0x3ffc0ff;
    const std::uint32_t r3 = (load32_le(k + 9) >> 6) & 0x3f03fff;
    const std::uint32_t r4 = (load32_le(k + 12) >> 8) & 0x00fffff;
    const std::uint32_t s1 = r1 * 5, s2 = r2 * 5, s3 = r3 * 5, s4 = r4 * 5;

    std::uint32_t h0 = 0, h1 = 0, h2 = 0, h3 = 0, h4 = 0;

    const std::uint8_t *m = bytes(message);
    std::size_t remaining = message.size();
    std::uint8_t last_block[16];

    while (remaining > 0)
    {
        const std::uint8_t *block = m;
        std::uint32_t hibit = 1u << 24; // the extra "1" bit above a full 16-byte block
        if (remaining < 16)
        {
            // Partial final block: append 0x01, pad with zeros, no extra high bit.
            for (std::size_t i = 0; i < 16; ++i)
            {
                last_block[i] = i < remaining ? m[i] : (i == remaining ? 1 : 0);
            }
            block = last_block;
            hibit = 0;
        }

        h0 += (load32_le(block + 0)) & 0x3ffffff;
        h1 += (load32_le(block + 3) >> 2) & 0x3ffffff;
        h2 += (load32_le(block + 6) >> 4) & 0x3ffffff;
        h3 += (load32_le(block + 9) >> 6) & 0x3ffffff;
        h4 += (load32_le(block + 12) >> 8) | hibit;

        // h *= r (mod 2^130 - 5)
        std::uint64_t d0 = (std::uint64_t)h0 * r0 + (std::uint64_t)h1 * s4 + (std::uint64_t)h2 * s3 + (std::uint64_t)h3 * s2 + (std::uint64_t)h4 * s1;
        std::uint64_t d1 = (std::uint64_t)h0 * r1 + (std::uint64_t)h1 * r0 + (std::uint64_t)h2 * s4 + (std::uint64_t)h3 * s3 + (std::uint64_t)h4 * s2;
        std::uint64_t d2 = (std::uint64_t)h0 * r2 + (std::uint64_t)h1 * r1 + (std::uint64_t)h2 * r0 + (std::uint64_t)h3 * s4 + (std::uint64_t)h4 * s3;
        std::uint64_t d3 = (std::uint64_t)h0 * r3 + (std::uint64_t)h1 * r2 + (std::uint64_t)h2 * r1 + (std::uint64_t)h3 * r0 + (std::uint64_t)h4 * s4;
        std::uint64_t d4 = (std::uint64_t)h0 * r4 + (std::uint64_t)h1 * r3 + (std::uint64_t)h2 * r2 + (std::uint64_t)h3 * r1 + (std::uint64_t)h4 * r0;

        std::uint32_t c;
        c = (std::uint32_t)(d0 >> 26); h0 = (std::uint32_t)d0 & 0x3ffffff;
        d1 += c; c = (std::uint32_t)(d1 >> 26); h1 = (std::uint32_t)d1 & 0x3ffffff;
        d2 += c; c = (std::uint32_t)(d2 >> 26); h2 = (std::uint32_t)d2 & 0x3ffffff;
        d3 += c; c = (std::uint32_t)(d3 >> 26); h3 = (std::uint32_t)d3 & 0x3ffffff;
        d4 += c; c = (std::uint32_t)(d4 >> 26); h4 = (std::uint32_t)d4 & 0x3ffffff;
        h0 += c * 5; c = h0 >> 26; h0 &= 0x3ffffff;
        h1 += c;

        std::size_t used = remaining < 16 ? remaining : 16;
        m += used;
        remaining -= used;
    }

    // Fully carry h
    std::uint32_t c;
    c = h1 >> 26; h1 &= 0x3ffffff;
    h2 += c; c = h2 >> 26; h2 &= 0x3ffffff;
    h3 += c; c = h3 >> 26; h3 &= 0x3ffffff;
    h4 += c; c = h4 >> 26; h4 &= 0x3ffffff;
    h0 += c * 5; c = h0 >> 26; h0 &= 0x3ffffff;
    h1 += c;

    // Compute h - p (p = 2^130 - 5) and pick it if h >= p, without branching
    std::uint32_t g0 = h0 + 5; c = g0 >> 26; g0 &= 0x3ffffff;
    std::uint32_t g1 = h1 + c; c = g1 >> 26; g1 &= 0x3ffffff;
    std::uint32_t g2 = h2 + c; c = g2 >> 26; g2 &= 0x3ffffff;
    std::uint32_t g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    std::uint32_t g4 = h4 + c - (1u << 26);

    std::uint32_t mask = (g4 >> 31) - 1; // all ones if h >= p
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;

    // h = h mod 2^128, packed into four 32-bit words
    h0 = (h0) | (h1 << 26);
    h1 = (h1 >> 6) | (h2 << 20);
    h2 = (h2 >> 12) | (h3 << 14);
    h3 = (h3 >> 18) | (h4 << 8);

    // tag = (h + s) mod 2^128, s = last 16 bytes of the key
    std::uint64_t f;
    f = (std::uint64_t)h0 + load32_le(k + 16); h0 = (std::uint32_t)f;
    f = (std::uint64_t)h1 + load32_le(k + 20) + (f >> 32); h1 = (std::uint32_t)f;
    f = (std::uint64_t)h2 + load32_le(k + 24) + (f >> 32); h2 = (std::uint32_t)f;
    f = (std::uint64_t)h3 + load32_le(k + 28) + (f >> 32); h3 = (std::uint32_t)f;

    std::array<std::uint8_t, TAG_SIZE> tag;
    store32_le(tag.data() + 0, h0);
    store32_le(tag.data() + 4, h1);
    store32_le(tag.data() + 8, h2);
    store32_le(tag.data() + 12, h3);
    return tag;
}

std::string Encryption::aead_seal(const Key &key, const Nonce &nonce, const std::string &aad, const std::string &plaintext)
{
    std::array<std::uint8_t, 32> one_time_key = poly1305_key_gen(key, nonce);
    std::string ciphertext = chacha20_xor(key, 1, nonce, plaintext);
    std::array<std::uint8_t, TAG_SIZE> tag = poly1305(one_time_key, aead_mac_data(aad, ciphertext));
    secure_zero(one_time_key.data(), one_time_key.size());
    ciphertext.append(reinterpret_cast<const char *>(tag.data()), tag.size());
    return ciphertext;
}

bool Encryption::aead_open(const Key &key, const Nonce &nonce, const std::string &aad, const std::string &sealed, std::string &plaintext)
{
    if (sealed.size() < TAG_SIZE)
    {
        return false;
    }
    std::string ciphertext = sealed.substr(0, sealed.size() - TAG_SIZE);
    std::array<std::uint8_t, 32> one_time_key = poly1305_key_gen(key, nonce);
    std::array<std::uint8_t, TAG_SIZE> expected = poly1305(one_time_key, aead_mac_data(aad, ciphertext));
    secure_zero(one_time_key.data(), one_time_key.size());

    // Check the tag before decrypting anything.
    if (!equal_constant_time(expected.data(), bytes(sealed) + ciphertext.size(), TAG_SIZE))
    {
        return false;
    }
    plaintext = chacha20_xor(key, 1, nonce, ciphertext);
    return true;
}

std::string Encryption::base64_encode(const std::string &data)
{
    std::string out;
    out.reserve((data.size() + 2) / 3 * 4);
    const std::uint8_t *p = bytes(data);
    std::size_t i = 0;
    for (; i + 3 <= data.size(); i += 3)
    {
        std::uint32_t v = (p[i] << 16) | (p[i + 1] << 8) | p[i + 2];
        out.push_back(BASE64_ALPHABET[(v >> 18) & 63]);
        out.push_back(BASE64_ALPHABET[(v >> 12) & 63]);
        out.push_back(BASE64_ALPHABET[(v >> 6) & 63]);
        out.push_back(BASE64_ALPHABET[v & 63]);
    }
    if (data.size() - i == 1)
    {
        std::uint32_t v = p[i] << 16;
        out.push_back(BASE64_ALPHABET[(v >> 18) & 63]);
        out.push_back(BASE64_ALPHABET[(v >> 12) & 63]);
        out += "==";
    }
    else if (data.size() - i == 2)
    {
        std::uint32_t v = (p[i] << 16) | (p[i + 1] << 8);
        out.push_back(BASE64_ALPHABET[(v >> 18) & 63]);
        out.push_back(BASE64_ALPHABET[(v >> 12) & 63]);
        out.push_back(BASE64_ALPHABET[(v >> 6) & 63]);
        out.push_back('=');
    }
    return out;
}

bool Encryption::base64_decode(const std::string &text, std::string &data)
{
    if (text.size() % 4 != 0)
    {
        return false;
    }
    data.clear();
    data.reserve(text.size() / 4 * 3);
    for (std::size_t i = 0; i < text.size(); i += 4)
    {
        bool last = (i + 4 == text.size());
        int a = base64_value(text[i]);
        int b = base64_value(text[i + 1]);
        int c = (last && text[i + 2] == '=') ? -2 : base64_value(text[i + 2]);
        int d = (last && text[i + 3] == '=') ? -2 : base64_value(text[i + 3]);
        if (a < 0 || b < 0 || c == -1 || d == -1 || (c == -2 && d != -2))
        {
            return false;
        }
        std::uint32_t v = (a << 18) | (b << 12) | ((c < 0 ? 0 : c) << 6) | (d < 0 ? 0 : d);
        data.push_back(static_cast<char>((v >> 16) & 0xff));
        if (c >= 0) data.push_back(static_cast<char>((v >> 8) & 0xff));
        if (d >= 0) data.push_back(static_cast<char>(v & 0xff));
    }
    return true;
}

// -------------------------------------------------------------------------------------------
// Password encryption
// -------------------------------------------------------------------------------------------

Encryption::Encryption(const Key &key) : key(key) {}

Encryption::~Encryption()
{
    secure_zero(this->key.data(), this->key.size());
}

Encryption::Nonce Encryption::random_nonce()
{
    Nonce nonce;
    fill_random(nonce.data(), nonce.size());
    return nonce;
}

std::string Encryption::encrypt(std::string input) const
{
    Nonce nonce = random_nonce();
    std::string sealed = aead_seal(this->key, nonce, PREFIX, input);
    secure_zero(input.data(), input.size());

    std::string payload(reinterpret_cast<const char *>(nonce.data()), nonce.size());
    payload += sealed;
    return PREFIX + base64_encode(payload);
}

bool Encryption::try_decrypt(const std::string &input, std::string &output) const
{
    if (input.compare(0, PREFIX.size(), PREFIX) != 0)
    {
        return false; // not an encrypted value (e.g. a plain-text password from before encryption)
    }
    std::string payload;
    if (!base64_decode(input.substr(PREFIX.size()), payload) || payload.size() < NONCE_SIZE + TAG_SIZE)
    {
        return false;
    }
    Nonce nonce;
    for (std::size_t i = 0; i < NONCE_SIZE; ++i)
    {
        nonce[i] = static_cast<std::uint8_t>(payload[i]);
    }
    return aead_open(this->key, nonce, PREFIX, payload.substr(NONCE_SIZE), output);
}

std::string Encryption::decrypt(std::string input) const
{
    std::string output;
    if (!this->try_decrypt(input, output))
    {
        throw DecryptionError("The value could not be decrypted: it is not encrypted, was encrypted with a different key, or was modified.");
    }
    return output;
}

// -------------------------------------------------------------------------------------------
// Key file
// -------------------------------------------------------------------------------------------

std::string Encryption::key_file_path(const std::string &db_path)
{
    return db_path + ".key";
}

Encryption Encryption::from_key_file(const std::string &db_path)
{
    namespace fs = std::filesystem;
    const std::string path = key_file_path(db_path);
    // The path is UTF-8 (both GUIs pass UTF-8); build the filesystem path from char8_t so
    // non-ASCII folder names work on Windows too.
    const fs::path file_path(std::u8string(path.begin(), path.end()));
    std::error_code ec;

    Key key{};
    if (fs::exists(file_path, ec))
    {
        // Load the existing key: 64 hex characters (whitespace around them is ignored).
        std::ifstream in(file_path, std::ios::binary);
        std::stringstream contents;
        contents << in.rdbuf();
        if (!in.good() && !in.eof())
        {
            throw std::runtime_error("Could not read the encryption key file: " + path);
        }
        std::string hex;
        for (char ch : contents.str())
        {
            if (ch != ' ' && ch != '\r' && ch != '\n' && ch != '\t')
            {
                hex.push_back(ch);
            }
        }
        if (hex.size() != KEY_SIZE * 2)
        {
            throw std::runtime_error("The encryption key file is not valid (expected 64 hex characters): " + path);
        }
        for (std::size_t i = 0; i < KEY_SIZE; ++i)
        {
            int hi = hex_value(hex[2 * i]);
            int lo = hex_value(hex[2 * i + 1]);
            if (hi < 0 || lo < 0)
            {
                throw std::runtime_error("The encryption key file is not valid (expected 64 hex characters): " + path);
            }
            key[i] = static_cast<std::uint8_t>((hi << 4) | lo);
        }
        secure_zero(hex.data(), hex.size());
    }
    else
    {
        // First run: create a new random key. Never overwrite an existing file (that would make
        // every saved password unreadable).
        fill_random(key.data(), key.size());
        static const char HEX_DIGITS[] = "0123456789abcdef";
        std::string hex;
        for (std::uint8_t b : key)
        {
            hex.push_back(HEX_DIGITS[b >> 4]);
            hex.push_back(HEX_DIGITS[b & 15]);
        }
        hex.push_back('\n');

        std::ofstream out(file_path, std::ios::binary | std::ios::trunc);
        out << hex;
        out.close();
        secure_zero(hex.data(), hex.size());
        if (!out)
        {
            throw std::runtime_error("Could not create the encryption key file: " + path);
        }
        // Owner read/write only (on Windows this just clears the read-only flag).
        fs::permissions(file_path, fs::perms::owner_read | fs::perms::owner_write, fs::perm_options::replace, ec);
    }

    Encryption result(key);
    secure_zero(key.data(), key.size());
    return result;
}
